write('deploy/enable-all-paper-persistence.sh', '#!/usr/bin/env bash\nset -Eeuo pipefail\nAPP_DIR="${ALPHA_WEATHER_APP_DIR:-${HOME}/polymarket-weather-paper-app}"\nCONFIG_DIR="${ALPHA_CONFIG_DIR:-${HOME}/.polymarket-edge-scanner}"\nDB_PATH="${WEATHER_PAPER_DB_PATH:-/var/lib/polymarket-weather-paper/weather-paper.sqlite}"\nSTATUS_PATH="${WEATHER_PAPER_STATUS_PATH:-/var/lib/polymarket-weather-paper/status.json}"\nRELEASE_FILE="${CONFIG_DIR}/weather-paper-release.sha"\nSTART_FILE="${CONFIG_DIR}/all-paper-final-start.epoch"\nAUTH=/usr/local/libexec/polymarket-weather-paper-v3/authority.py\nUNIT=polymarket-weather-paper.service\nBACKUP_UNIT=polymarket-weather-paper-backup.service\nBACKUP_TIMER=polymarket-weather-paper-backup.timer\nSHA="${1:-}"; GEN="${2:-}"\nRUNTIME_ROOT=/var/lib/polymarket-weather-paper-runtime\nSRC="${RUNTIME_ROOT}/releases/${SHA}/source"; PY="${RUNTIME_ROOT}/releases/${SHA}/venv/bin/python"\nfail(){ printf \'ERROR: %s\\n\' "$*" >&2; exit 1; }\n[[ "${SHA}" =~ ^[0-9a-f]{40}$ && "${GEN}" =~ ^[0-9a-f]{64}$ ]] || fail "usage: $0 <exact-approved-release-sha> <generation-id>"\n[[ -x "${AUTH}" && -x "${PY}" && -f "${START_FILE}" ]] || fail "authority/runtime/start evidence missing"\nsystemctl is-active --quiet "${UNIT}" || fail "accepted service is not active"\n! systemctl is-enabled --quiet "${UNIT}" || fail "service already enabled"\nsudo /usr/bin/env -i PATH=/usr/bin:/bin HOME=/nonexistent LANG=C.UTF-8 /usr/bin/python3 "${AUTH}" verify-process --generation-id "${GEN}" --candidate-sha "${SHA}"\nSTART="$(tr -d \'[:space:]\' <"${START_FILE}")"\n"${PY}" -I -s -E "${SRC}/deploy/verify-all-paper-first-cycle-v2.py" --status "${STATUS_PATH}" --release-sha "${SHA}" --not-before "${START}" --timeout-seconds 120 --max-age-seconds 900 --output "${CONFIG_DIR}/all-paper-persistence-cycle.json"\n"${PY}" -I -s -E "${SRC}/deploy/verify-operator-sync-complete.py" --db "${DB_PATH}" --output "${CONFIG_DIR}/all-paper-persistence-operator-sync.json"\n"${PY}" -I -s -E "${SRC}/deploy/verify-three-layer-validation-status.py" --status "${STATUS_PATH}" --release-sha "${SHA}" --not-before "${START}" --timeout-seconds 60 --max-age-seconds 900 --output "${CONFIG_DIR}/all-paper-persistence-three-layer.json"\n"${PY}" -I -s -E "${SRC}/deploy/verify-three-layer-fresh-capture.py" --status "${STATUS_PATH}" --db "${DB_PATH}" --release-sha "${SHA}" --not-before "${START}" --timeout-seconds 60 --max-age-seconds 900 --output "${CONFIG_DIR}/all-paper-persistence-fresh-capture.json"\nbash "${SRC}/deploy/setup-weather-paper-backup-service.sh"\npersistence_attempted=0\nrollback_persistence(){\n  code=$?\n  if (( code != 0 && persistence_attempted == 1 )); then\n    sudo systemctl disable --now "${BACKUP_TIMER}" >/dev/null 2>&1 || true\n    sudo systemctl disable "${UNIT}" >/dev/null 2>&1 || true\n  fi\n  exit "${code}"\n}\ntrap rollback_persistence EXIT\nsudo systemctl start "${BACKUP_UNIT}"\nsystemctl is-failed --quiet "${BACKUP_UNIT}" 2>/dev/null && fail "initial verified paper backup failed"\npersistence_attempted=1\nsudo systemctl enable "${UNIT}"\nsudo systemctl enable --now "${BACKUP_TIMER}"\nsystemctl is-enabled --quiet "${UNIT}" || fail "service not enabled"\nsystemctl is-active --quiet "${UNIT}" || fail "service stopped while enabling persistence"\nsudo /usr/bin/env -i PATH=/usr/bin:/bin HOME=/nonexistent LANG=C.UTF-8 /usr/bin/python3 "${AUTH}" verify-process --generation-id "${GEN}" --candidate-sha "${SHA}"\n"${PY}" -I -s -E "${SRC}/deploy/verify-operator-sync-complete.py" --db "${DB_PATH}" >/dev/null\nsudo /usr/bin/env -i PATH=/usr/bin:/bin HOME=/nonexistent LANG=C.UTF-8 /usr/bin/python3 "${AUTH}" finalize --generation-id "${GEN}" --candidate-sha "${SHA}"\ntrap - EXIT\nprintf \'PASS: immutable V10 PAPER bot enabled for restart persistence. Release=%s generation=%s\\n\' "${SHA}" "${GEN}"\n')
write('deploy/attest-all-paper-runtime-v2.py', '#!/usr/bin/env python3\nfrom __future__ import annotations\n\n"""Additive V10 runtime attestation for the independently prepared immutable release."""\n\nimport argparse\nimport json\nimport os\nimport subprocess\nfrom pathlib import Path\n\nFINAL_MODULE = "polymarket_scanner.weather_only_live_paper_all_signals_final_v10"\nAUTH = "/usr/local/libexec/polymarket-weather-paper-v3/authority.py"\nRUNTIME_ROOT = Path("/var/lib/polymarket-weather-paper-runtime")\nFORBIDDEN = {\n    "HTTP_PROXY","HTTPS_PROXY","ALL_PROXY","NO_PROXY","http_proxy","https_proxy",\n    "all_proxy","no_proxy","SSL_CERT_FILE","SSL_CERT_DIR","PYTHONPATH","PYTHONHOME",\n    "PYTHONUSERBASE","PYTHONSTARTUP","PYTHONINSPECT","PYTHONWARNINGS",\n    "PYTHONBREAKPOINT","LD_PRELOAD","LD_LIBRARY_PATH","BASH_ENV","ENV","CDPATH",\n    "GIT_DIR","GIT_WORK_TREE","GIT_CONFIG_GLOBAL","GIT_CONFIG_SYSTEM",\n}\nALLOWED = {\n    "PATH","HOME","LANG","PYTHONUNBUFFERED","PYTHONNOUSERSITE",\n    "PYTHONDONTWRITEBYTECODE","ALPHA_DISABLE_DOTENV","ALPHA_RELEASE_SHA",\n    "ALPHA_CUTOVER_GENERATION","ALPHA_RUNTIME_SOURCE","TELEGRAM_BOT_TOKEN",\n    "TELEGRAM_CHAT_ID",\n}\n\n\ndef run(args: list[str], allow_nonzero: bool = False) -> subprocess.CompletedProcess[str]:\n    result = subprocess.run(args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)\n    if result.returncode and not allow_nonzero:\n        raise RuntimeError("ATTEST_COMMAND_FAILED:" + Path(args[0]).name)\n    return result\n\n\ndef proc_env(pid: int) -> dict[str, str]:\n    out = {}\n    for item in Path(f"/proc/{pid}/environ").read_bytes().split(b"\\0"):\n        if b"=" in item:\n            k, v = item.split(b"=", 1)\n            out[k.decode("utf-8")] = v.decode("utf-8")\n    return out\n\n\ndef main() -> int:\n    p = argparse.ArgumentParser()\n    p.add_argument("--app-dir", type=Path, required=True)\n    p.add_argument("--release-file", type=Path, required=True)\n    p.add_argument("--db", type=Path, required=True)\n    p.add_argument("--status", type=Path)\n    p.add_argument("--unit", default="polymarket-weather-paper.service")\n    p.add_argument("--require-active", action="store_true")\n    p.add_argument("--output", type=Path)\n    p.add_argument("--expected-release-sha", required=True)\n    p.add_argument("--generation-id", required=True)\n    a = p.parse_args()\n    sha = a.expected_release_sha.strip().lower()\n    gen = a.generation_id.strip().lower()\n    source = (RUNTIME_ROOT / "releases" / sha / "source").resolve()\n    python = (RUNTIME_ROOT / "releases" / sha / "venv/bin/python").resolve()\n    payload: dict[str, object]\n    try:\n        if len(sha) != 40 or len(gen) != 64:\n            raise RuntimeError("ATTEST_IDENTITY_INVALID")\n        if run(["git","-C",str(a.app_dir),"rev-parse","HEAD"]).stdout.strip().lower() != sha:\n            raise RuntimeError("ATTEST_STAGING_CHECKOUT_MISMATCH")\n        if a.release_file.read_text(encoding="utf-8").strip().lower() != sha:\n            raise RuntimeError("ATTEST_RELEASE_MARKER_MISMATCH")\n        unit = run(["systemctl","cat",a.unit]).stdout\n        expected_exec = f"{python} -I -s -E -m {FINAL_MODULE}"\n        if expected_exec not in unit or f"WorkingDirectory={source}" not in unit:\n            raise RuntimeError("ATTEST_UNIT_RUNTIME_IDENTITY_MISMATCH")\n        if f"ALPHA_CUTOVER_GENERATION={gen}" not in unit or f"ALPHA_RELEASE_SHA={sha}" not in unit:\n            raise RuntimeError("ATTEST_UNIT_GENERATION_IDENTITY_MISMATCH")\n        active = run(["systemctl","is-active","--quiet",a.unit], allow_nonzero=True).returncode == 0\n        if a.require_active and not active:\n            raise RuntimeError("ATTEST_ACTIVE_REQUIRED")\n        process = None\n        if active:\n            raw = run(["systemctl","show",a.unit,"--property","MainPID","--value"]).stdout.strip()\n            pid = int(raw)\n            if pid <= 1:\n                raise RuntimeError("ATTEST_PID_INVALID")\n            exe = Path(os.readlink(f"/proc/{pid}/exe")).resolve()\n            cwd = Path(os.readlink(f"/proc/{pid}/cwd")).resolve()\n            argv = [x.decode("utf-8") for x in Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\\0") if x]\n            env = proc_env(pid)\n            if exe != python or cwd != source:\n                raise RuntimeError("ATTEST_PROCESS_PATH_MISMATCH")\n            if not argv or Path(argv[0]).resolve() != python or "-I" not in argv or "-s" not in argv or "-E" not in argv or FINAL_MODULE not in argv:\n                raise RuntimeError("ATTEST_PROCESS_ARGV_MISMATCH")\n            leaked = set(env) & FORBIDDEN\n            unexpected = set(env) - ALLOWED\n            if leaked:\n                raise RuntimeError("ATTEST_FORBIDDEN_ENV:" + ",".join(sorted(leaked)))\n            if unexpected:\n                raise RuntimeError("ATTEST_UNEXPECTED_ENV:" + ",".join(sorted(unexpected)))\n            if env.get("PYTHONNOUSERSITE") != "1" or env.get("ALPHA_RELEASE_SHA") != sha or env.get("ALPHA_CUTOVER_GENERATION") != gen or env.get("ALPHA_RUNTIME_SOURCE") != str(source):\n                raise RuntimeError("ATTEST_PROCESS_ENV_IDENTITY_MISMATCH")\n            process = {"pid":pid,"executable":str(exe),"cwd":str(cwd),"environment_keys":sorted(env)}\n        status = {}\n        if a.status and a.status.exists():\n            status = json.loads(a.status.read_text(encoding="utf-8"))\n            if status.get("runtime_python_executable") != str(python):\n                raise RuntimeError("ATTEST_STATUS_PYTHON_MISMATCH")\n            if status.get("runtime_source_path") != str(source):\n                raise RuntimeError("ATTEST_STATUS_SOURCE_MISMATCH")\n            if status.get("python_user_site_disabled") is not True or status.get("application_modules_from_approved_source") is not True:\n                raise RuntimeError("ATTEST_STATUS_IMPORT_BOUNDARY_UNPROVEN")\n            allowed_roots = (str(source), str((RUNTIME_ROOT/"releases"/sha/"venv").resolve()), "/usr/lib", "/usr/local/lib")\n            for item in status.get("runtime_sys_path") or []:\n                if not item:\n                    continue\n                rp = str(Path(item).resolve())\n                if not any(rp == root or rp.startswith(root.rstrip("/") + "/") for root in allowed_roots):\n                    raise RuntimeError("ATTEST_SYS_PATH_UNAPPROVED:" + rp)\n        payload = {\n            "acceptance":"PASS_ALL_PAPER_RUNTIME_V10_ATTESTATION",\n            "release_sha":sha,"generation_id":gen,"final_module":FINAL_MODULE,\n            "immutable_runtime_source":str(source),"immutable_runtime_python":str(python),\n            "active":active,"process":process,"forbidden_environment_absent":True,\n            "financial_authority":False,"automatic_order_placement":False,\n            "wallet_or_order_api_loaded":False,\n        }\n        code = 0\n    except Exception as exc:\n        payload = {"acceptance":"FAIL_ALL_PAPER_RUNTIME_V10_ATTESTATION","error":getattr(exc,"code",str(exc))}\n        code = 2\n    text = json.dumps(payload, sort_keys=True, indent=2) + "\\n"\n    if a.output:\n        a.output.parent.mkdir(parents=True, exist_ok=True)\n        a.output.write_text(text, encoding="utf-8")\n        os.chmod(a.output, 0o600)\n    print(text, end="")\n    return code\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n')
write('deploy/render-all-paper-unit.py', '"""CI mirror of the independently pinned V10 unit template; never installs or starts it."""\nfrom __future__ import annotations\nimport argparse,re\nfrom pathlib import Path\n\nFINAL_MODULE="polymarket_scanner.weather_only_live_paper_all_signals_final_v10"\nRUNTIME_ROOT=Path("/var/lib/polymarket-weather-paper-runtime")\nAUTH="/usr/local/libexec/polymarket-weather-paper-v3/authority.py"\nFORBIDDEN=(\n"ALL_PROXY","BASH_ENV","CDPATH","ENV","GIT_CONFIG_GLOBAL","GIT_CONFIG_SYSTEM","GIT_DIR","GIT_WORK_TREE",\n"HTTP_PROXY","HTTPS_PROXY","LD_LIBRARY_PATH","LD_PRELOAD","NO_PROXY","PYTHONBREAKPOINT","PYTHONHOME",\n"PYTHONINSPECT","PYTHONPATH","PYTHONSTARTUP","PYTHONUSERBASE","PYTHONWARNINGS","SSL_CERT_DIR","SSL_CERT_FILE",\n"all_proxy","http_proxy","https_proxy","no_proxy")\n\ndef render(app_dir:Path,config_dir:Path,user:str,release_sha:str,generation_id:str)->str:\n    for value in (str(app_dir),str(config_dir),user,release_sha,generation_id):\n        if not re.fullmatch(r"[/A-Za-z0-9_.-]+",value):\n            raise ValueError("unsafe service identity")\n    if not app_dir.is_absolute() or not config_dir.is_absolute() or not re.fullmatch(r"[0-9a-f]{40}",release_sha) or not re.fullmatch(r"[0-9a-f]{64}",generation_id):\n        raise ValueError("invalid service identity")\n    root=RUNTIME_ROOT/"releases"/release_sha; source=root/"source"; python=root/"venv/bin/python"\n    state="/var/lib/polymarket-weather-paper"; release_file=config_dir/"weather-paper-release.sha"; env_file=config_dir/"weather-paper.env"; unset=" ".join(FORBIDDEN)\n    return f"""[Unit]\nDescription=Polymarket final all-weather PAPER research runtime V10\nWants=network-online.target\nAfter=network-online.target\nStartLimitIntervalSec=600\nStartLimitBurst=3\n\n[Service]\nType=simple\nUser={user}\nWorkingDirectory={source}\nEnvironment=PYTHONUNBUFFERED=1\nEnvironment=PYTHONNOUSERSITE=1\nEnvironment=PYTHONDONTWRITEBYTECODE=1\nEnvironment=ALPHA_DISABLE_DOTENV=1\nEnvironment=ALPHA_RELEASE_SHA={release_sha}\nEnvironment=ALPHA_CUTOVER_GENERATION={generation_id}\nEnvironment=ALPHA_RUNTIME_SOURCE={source}\nUnsetEnvironment={unset}\nEnvironmentFile={env_file}\nExecStartPre=+/usr/bin/python3 {AUTH} verify-runtime-files --generation-id {generation_id} --candidate-sha {release_sha}\nExecStart=/usr/bin/env -i PATH=/usr/bin:/bin HOME=/nonexistent LANG=C.UTF-8 PYTHONUNBUFFERED=1 PYTHONNOUSERSITE=1 PYTHONDONTWRITEBYTECODE=1 ALPHA_DISABLE_DOTENV=1 ALPHA_RELEASE_SHA={release_sha} ALPHA_CUTOVER_GENERATION={generation_id} ALPHA_RUNTIME_SOURCE={source} TELEGRAM_BOT_TOKEN=${{TELEGRAM_BOT_TOKEN}} TELEGRAM_CHAT_ID=${{TELEGRAM_CHAT_ID}} {python} -I -s -E -m {FINAL_MODULE} --db {state}/weather-paper.sqlite --status {state}/status.json --release-file {release_file} --interval-seconds 180 --forecast-cache-seconds 900 --forecast-raw-gap-min 0.08 --max-forecast-events 6 --paper-stake-usd 10\nRestart=on-failure\nRestartSec=15\nTimeoutStopSec=20\nMemoryHigh=280M\nMemoryMax=350M\nMemorySwapMax=0\nTasksMax=48\nNice=5\nCPUWeight=70\nIOWeight=50\nNoNewPrivileges=true\nPrivateTmp=true\nPrivateDevices=true\nProtectHome=read-only\nProtectSystem=strict\nProtectKernelTunables=true\nProtectKernelModules=true\nProtectControlGroups=true\nRestrictSUIDSGID=true\nLockPersonality=true\nCapabilityBoundingSet=\nAmbientCapabilities=\nStateDirectory=polymarket-weather-paper\nStateDirectoryMode=0700\nReadWritePaths={state}\nUMask=0077\n\n[Install]\nWantedBy=multi-user.target\n"""\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("--app-dir",type=Path,required=True); p.add_argument("--config-dir",type=Path,required=True); p.add_argument("--user",required=True); p.add_argument("--release-sha",required=True); p.add_argument("--generation-id",required=True); p.add_argument("--output",type=Path,required=True); a=p.parse_args()\n    a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(render(a.app_dir,a.config_dir,a.user,a.release_sha,a.generation_id),encoding="utf-8")\nif __name__=="__main__": main()\n')
write('polymarket_scanner/weather_only_operator_state_corrective_v5.py', 'from __future__ import annotations\n\n"""Atomic delivered-terminal transition with exact identity and operator-sync creation."""\n\nimport math\nimport time\n\nfrom .weather_only_operator_state_corrective import TERMINAL_VISIBLE_STATUSES, OPERATOR_SYNC_APPLIED, OPERATOR_SYNC_PENDING, _sha\nfrom .weather_only_operator_state_corrective_v4 import OperatorStatePostReceiptStoreV4\nfrom .weather_only_paper_positions import WeatherPaperPositionError, _payload\n\nOPERATOR_STATE_CORRECTIVE_V5_VERSION = "weather_operator_state_v5_atomic_delivered_terminal_sync"\n_ALLOWED_PRESTATES = {\n    "EXPIRED": {"PENDING_DELIVERY", "POST_RECEIPT_RECHECK"},\n    "PAPER_ACCOUNTING_ERROR": {"POST_RECEIPT_RECHECK"},\n    "POST_RECEIPT_NOT_ACTIONABLE": {"POST_RECEIPT_RECHECK"},\n    "MAKER_NOT_ACTIVATED": {"POST_RECEIPT_RECHECK"},\n    "MAKER_NOT_ACTIVATED_RESTART_COVERAGE_LOST": {"POST_RECEIPT_RECHECK", "PENDING_DELIVERY"},\n    "ACTIONABILITY_UNPROVEN": {"POST_RECEIPT_RECHECK"},\n}\n\n\nclass OperatorStatePostReceiptStoreV5(OperatorStatePostReceiptStoreV4):\n    def terminalize_delivered_signal(\n        self,\n        signal_id: int,\n        *,\n        terminal_status: str,\n        reason: str,\n        decision_id: str,\n        event_id: str,\n        market_id: str | None,\n        side: str | None,\n        token_id: str | None = None,\n        recorded_at: float | None = None,\n    ) -> None:\n        sid = int(signal_id)\n        status = str(terminal_status or "").strip().upper()\n        why = str(reason or "").strip()\n        decision = str(decision_id or "").strip()\n        expected_event = str(event_id or "").strip()\n        expected_market = None if market_id is None else str(market_id).strip()\n        expected_side = None if side is None else str(side).strip().upper()\n        expected_token = None if token_id is None else str(token_id).strip()\n        if sid <= 0 or status not in TERMINAL_VISIBLE_STATUSES or status not in _ALLOWED_PRESTATES:\n            raise WeatherPaperPositionError("DELIVERED_TERMINAL_STATUS_INVALID")\n        if not why or not decision or not expected_event:\n            raise WeatherPaperPositionError("DELIVERED_TERMINAL_IDENTITY_INVALID")\n        at = time.time() if recorded_at is None else float(recorded_at)\n        if not math.isfinite(at) or at < 0:\n            raise WeatherPaperPositionError("DELIVERED_TERMINAL_TIME_INVALID")\n\n        with self._conn() as db:\n            try:\n                db.execute("BEGIN IMMEDIATE")\n                row = db.execute("SELECT * FROM weather_paper_signals WHERE id=?", (sid,)).fetchone()\n                if row is None:\n                    raise WeatherPaperPositionError("V5_SIGNAL_NOT_FOUND")\n                signal = dict(row)\n                payload = _payload(signal.get("payload_json"))\n                receipt = signal.get("telegram_message_id")\n                sent_at = signal.get("telegram_sent_at")\n                if isinstance(receipt, bool) or not isinstance(receipt, int) or receipt <= 0:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_RECEIPT_MISSING")\n                if isinstance(sent_at, bool) or not isinstance(sent_at, (int, float)) or not math.isfinite(float(sent_at)) or float(sent_at) < 0:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_RECEIPT_TIME_INVALID")\n                current = str(signal.get("status") or "").strip().upper()\n                if current == status:\n                    existing = db.execute(\n                        "SELECT state,reason FROM weather_paper_operator_sync WHERE signal_id=?", (sid,)\n                    ).fetchone()\n                    if existing is None or str(existing["reason"] or "") != why:\n                        raise WeatherPaperPositionError("DELIVERED_TERMINAL_IDEMPOTENCY_CONFLICT")\n                    db.execute("COMMIT")\n                    return\n                if current not in _ALLOWED_PRESTATES[status]:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_PRESTATE_INVALID")\n                if str(signal.get("event_id") or "") != expected_event:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_EVENT_ID_MISMATCH")\n                actual_market = str(signal.get("market_id") or "").strip() or None\n                if actual_market != expected_market:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_MARKET_ID_MISMATCH")\n                actual_side = str(signal.get("side") or "").strip().upper() or None\n                if actual_side != expected_side:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_SIDE_MISMATCH")\n                actual_token = str(signal.get("token_id") or "").strip() or None\n                if expected_token is not None and actual_token != expected_token:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_TOKEN_ID_MISMATCH")\n                if actual_side in {"YES", "NO"} and not actual_token:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_TOKEN_IDENTITY_MISSING")\n\n                lane = str(signal.get("lane") or "")\n                payload_decision = str(payload.get("decision_id") or "").strip()\n                if lane == "weather_maker_virtual_bid":\n                    if decision != expected_event or str(payload.get("order_id") or "").strip() == "":\n                        raise WeatherPaperPositionError("DELIVERED_TERMINAL_MAKER_IDENTITY_INVALID")\n                    if str(payload.get("fingerprint") or "").strip() and str(payload.get("fingerprint")) != str(signal.get("fingerprint") or ""):\n                        raise WeatherPaperPositionError("DELIVERED_TERMINAL_FINGERPRINT_MISMATCH")\n                else:\n                    if not payload_decision or payload_decision != decision:\n                        raise WeatherPaperPositionError("DELIVERED_TERMINAL_DECISION_ID_MISMATCH")\n\n                db.execute("UPDATE weather_paper_signals SET status=? WHERE id=?", (status, sid))\n                db.execute(\n                    """INSERT INTO weather_paper_decisions(\n                         decision_id,event_id,market_id,side,outcome,reason,created_at\n                       ) VALUES(?,?,?,?,?,?,?)""",\n                    (decision, expected_event, expected_market, expected_side, status, why, at),\n                )\n                sync_row = dict(signal)\n                sync_row["status"] = status\n                message_text = self._sync_message(sync_row, why)\n                message_sha = _sha(message_text)\n                existing = db.execute(\n                    "SELECT state,reason,message_sha256 FROM weather_paper_operator_sync WHERE signal_id=?",\n                    (sid,),\n                ).fetchone()\n                if existing is not None and str(existing["state"]) == OPERATOR_SYNC_APPLIED:\n                    raise WeatherPaperPositionError("DELIVERED_TERMINAL_ALREADY_VISIBLE_CONFLICT")\n                db.execute(\n                    """INSERT INTO weather_paper_operator_sync(\n                         signal_id,telegram_message_id,base_fingerprint,terminal_status,\n                         reason,message_sha256,state,attempts,last_error,created_at,updated_at,\n                         applied_at,fingerprint_released\n                       ) VALUES(?,?,?,?,?,?,?,0,NULL,?,?,NULL,0)\n                       ON CONFLICT(signal_id) DO UPDATE SET\n                         terminal_status=excluded.terminal_status,\n                         reason=excluded.reason,\n                         message_sha256=excluded.message_sha256,\n                         state=?,\n                         last_error=NULL,\n                         updated_at=excluded.updated_at,\n                         applied_at=NULL""",\n                    (\n                        sid, int(receipt), str(signal.get("fingerprint") or ""), status, why,\n                        message_sha, OPERATOR_SYNC_PENDING, at, at, OPERATOR_SYNC_PENDING,\n                    ),\n                )\n                db.execute("COMMIT")\n            except Exception:\n                if db.in_transaction:\n                    db.execute("ROLLBACK")\n                raise\n')
write('polymarket_scanner/weather_only_live_paper_all_signals_final_v10.py', 'from __future__ import annotations\n\n"""Final V10: immutable runtime provenance, semantic truth, terminal sync, maker evidence."""\n\nimport argparse\nimport asyncio\nimport json\nimport os\nimport site\nimport sys\nfrom pathlib import Path\n\nfrom .weather_only_live_paper import DEFAULT_FORECAST_CACHE_SECONDS, DEFAULT_FORECAST_RAW_GAP_MIN, DEFAULT_INTERVAL_SECONDS, DEFAULT_MAX_FORECAST_EVENTS, WeatherLivePaperError, _atomic_json\nfrom .weather_only_live_paper_all_signals_final_v9 import (\n    FINAL_ALL_PAPER_RUNTIME_V9_VERSION,\n    MAX_GLOBAL_RECALL_REUSE_SECONDS,\n    TELEGRAM_EDIT_ABSENT,\n    FinalAllPaperWeatherLiveServiceV9,\n    FinalOperatorStateTelegram,\n)\nfrom .weather_only_live_paper_v2 import DEFAULT_PAPER_STAKE_USD\nfrom .weather_only_operator_state_corrective_v5 import OPERATOR_STATE_CORRECTIVE_V5_VERSION, OperatorStatePostReceiptStoreV5\nfrom .weather_only_maker_paper_accounting_v6 import MAKER_PAPER_ACCOUNTING_V6_VERSION, MakerPaperAccountingStoreV6\nfrom .weather_only_operator_commands_v10 import OperatorStateCommandControllerV10\nfrom .weather_only_paper_corrective import CorrectiveSettlementEngine\n\nFINAL_ALL_PAPER_RUNTIME_V10_VERSION = "final_all_paper_v10_immutable_runtime_semantic_terminal_maker_evidence"\nFORBIDDEN_CODE_ENV = (\n    "PYTHONPATH","PYTHONHOME","PYTHONUSERBASE","PYTHONSTARTUP","PYTHONINSPECT",\n    "PYTHONWARNINGS","PYTHONBREAKPOINT","LD_PRELOAD","LD_LIBRARY_PATH",\n)\n\n\ndef _approved_module_origins() -> tuple[bool, str | None]:\n    raw = os.environ.get("ALPHA_RUNTIME_SOURCE")\n    if not raw:\n        return False, None\n    root = Path(raw).resolve()\n    package_root = Path(__file__).resolve().parents[1]\n    if package_root != root:\n        raise RuntimeError("ALL_PAPER_RUNTIME_SOURCE_MODULE_ROOT_MISMATCH")\n    for name, module in tuple(sys.modules.items()):\n        if not name.startswith("polymarket_scanner"):\n            continue\n        path = getattr(module, "__file__", None)\n        if not path:\n            continue\n        resolved = Path(path).resolve()\n        if resolved != root and root not in resolved.parents:\n            raise RuntimeError("ALL_PAPER_APPLICATION_MODULE_OUTSIDE_APPROVED_SOURCE:" + name)\n    return True, str(root)\n\n\nclass FinalAllPaperWeatherLiveServiceV10(FinalAllPaperWeatherLiveServiceV9):\n    def __init__(self, **kwargs) -> None:\n        leaked = [x for x in FORBIDDEN_CODE_ENV if x in os.environ]\n        if leaked:\n            raise RuntimeError("ALL_PAPER_CODE_LOADING_ENVIRONMENT_FORBIDDEN:" + ",".join(sorted(leaked)))\n        if os.environ.get("PYTHONNOUSERSITE") != "1" or site.ENABLE_USER_SITE is not False:\n            raise RuntimeError("ALL_PAPER_USER_SITE_NOT_DISABLED")\n        deployment_identity = os.environ.get("ALPHA_RELEASE_SHA")\n        if deployment_identity:\n            source_ok, source_path = _approved_module_origins()\n            if not source_ok:\n                raise RuntimeError("ALL_PAPER_APPROVED_RUNTIME_SOURCE_MISSING")\n            if deployment_identity != self_release_from_env():\n                raise RuntimeError("ALL_PAPER_RELEASE_ENV_INVALID")\n        else:\n            source_path = None\n\n        super().__init__(**kwargs)\n        old_positions = self.positions\n        old_maker = self.maker_store\n        old_settlement = self.settlement\n        old_commands = self.commands\n        self.positions = OperatorStatePostReceiptStoreV5(self.db_path)\n        self.positions.reconcile_v5_after_restart()\n        self.positions.ensure_operator_sync_records()\n        old_maker.close()\n        self.maker_store = MakerPaperAccountingStoreV6(self.db_path)\n        self.settlement = CorrectiveSettlementEngine(store=self.positions, telegram=self.telegram)\n        self.commands = OperatorStateCommandControllerV10(\n            telegram=self.telegram, store=self.positions, maker_store=self.maker_store,\n            status_path=self.status_path, paper_stake_usd=self.paper_stake_usd\n        )\n        self._v10_old = (old_positions, old_settlement, old_commands)\n        self._v10_runtime_source = source_path\n\n    async def _terminalize_delivered_signal(self, signal_id: int, candidate: dict, *, status: str, reason: str) -> None:\n        await asyncio.to_thread(\n            self.positions.terminalize_delivered_signal,\n            signal_id,\n            terminal_status=status,\n            reason=str(reason),\n            decision_id=str(candidate.get("decision_id") or candidate.get("event_id") or signal_id),\n            event_id=str(candidate.get("event_id") or ""),\n            market_id=str(candidate.get("market_id") or "") or None,\n            side=str(candidate.get("side") or "") or None,\n            token_id=str(candidate.get("token_id") or "") or None,\n        )\n        sync = await self._sync_operator_messages()\n        if sync.get("healthy") is not True or list(sync.get("errors") or []):\n            raise WeatherLivePaperError("DELIVERED_TERMINAL_OPERATOR_SYNC_FAILED")\n\n    async def run_cycle(self) -> dict:\n        status = dict(await super().run_cycle())\n        recall = dict(status.get("global_weather_recall") or {})\n        semantic_complete = recall.get("weather_semantic_coverage_complete") is True\n        policy = str(recall.get("weather_semantic_product_policy") or "")\n        source_ok, source_path = _approved_module_origins() if os.environ.get("ALPHA_RUNTIME_SOURCE") else (False, None)\n        status.update({\n            "final_all_paper_runtime_v10_version": FINAL_ALL_PAPER_RUNTIME_V10_VERSION,\n            "final_all_paper_runtime_v9_version": FINAL_ALL_PAPER_RUNTIME_V9_VERSION,\n            "operator_state_corrective_v5_version": OPERATOR_STATE_CORRECTIVE_V5_VERSION,\n            "maker_paper_accounting_v6_version": MAKER_PAPER_ACCOUNTING_V6_VERSION,\n            "gamma_census_complete": recall.get("gamma_census_complete") is True,\n            "gamma_census_completed_at": recall.get("gamma_census_completed_at"),\n            "gamma_census_age_seconds": recall.get("gamma_census_age_seconds"),\n            "total_active_events_scanned": int(recall.get("total_active_events_scanned") or 0),\n            "weather_looking_events_discovered": int(recall.get("weather_looking_events") or 0),\n            "strict_supported_weather_events": int(recall.get("strict_supported_events") or 0),\n            "unsupported_weather_events": int(recall.get("unsupported_weather_events") or 0),\n            "unsupported_weather_reason_counts": dict(recall.get("unsupported_reason_counts") or {}),\n            "unsupported_weather_examples": list(recall.get("unsupported_examples") or []),\n            "weather_semantic_coverage_complete": semantic_complete,\n            "weather_semantic_coverage_status": recall.get("weather_semantic_coverage_status"),\n            "weather_semantic_product_policy": policy,\n            "global_weather_coverage_complete": semantic_complete,\n            "global_weather_recall_complete": recall.get("gamma_census_complete") is True,\n            "code_loading_environment_isolated": True,\n            "python_user_site_disabled": True,\n            "runtime_sys_path": list(sys.path),\n            "runtime_python_executable": str(Path(sys.executable).resolve()),\n            "runtime_prefix": sys.prefix,\n            "runtime_base_prefix": sys.base_prefix,\n            "runtime_source_path": source_path,\n            "application_modules_from_approved_source": source_ok,\n            "maker_legacy_queue_pnl_excluded": True,\n            "financial_authority": False,\n            "automatic_order_placement": False,\n            "wallet_or_order_api_loaded": False,\n        })\n        if policy != "STRICT_SUPPORTED_SUBSET":\n            status["cycle_ok"] = False\n            status["operator_all_lanes_healthy"] = False\n            status.setdefault("errors", []).append("WEATHER_SEMANTIC_POLICY_INVALID")\n        if os.environ.get("ALPHA_RELEASE_SHA") and not source_ok:\n            status["cycle_ok"] = False\n            status["operator_all_lanes_healthy"] = False\n            status.setdefault("errors", []).append("IMMUTABLE_RUNTIME_SOURCE_UNPROVEN")\n        _atomic_json(self.status_path, status)\n        return status\n\n\ndef self_release_from_env() -> str:\n    value = str(os.environ.get("ALPHA_RELEASE_SHA") or "").strip().lower()\n    if len(value) != 40 or any(c not in "0123456789abcdef" for c in value):\n        raise RuntimeError("ALL_PAPER_RELEASE_ENV_INVALID")\n    return value\n\n\nasync def _main(a):\n    service = FinalAllPaperWeatherLiveServiceV10(\n        db_path=a.db,status_path=a.status,release_file=a.release_file,\n        interval_seconds=a.interval_seconds,forecast_cache_seconds=a.forecast_cache_seconds,\n        forecast_raw_gap_min=a.forecast_raw_gap_min,max_forecast_events=a.max_forecast_events,\n        paper_stake_usd=a.paper_stake_usd,\n    )\n    try:\n        if a.once:\n            await service.send_startup()\n            status = await service.run_cycle()\n            print(json.dumps(status,sort_keys=True,indent=2))\n            return 0 if status.get("operator_all_lanes_healthy") is True else 2\n        await service.loop()\n        return 0\n    finally:\n        await service.close()\n\n\ndef main():\n    p=argparse.ArgumentParser()\n    p.add_argument("--db",type=Path,required=True); p.add_argument("--status",type=Path,required=True); p.add_argument("--release-file",type=Path,required=True)\n    p.add_argument("--interval-seconds",type=float,default=DEFAULT_INTERVAL_SECONDS); p.add_argument("--forecast-cache-seconds",type=float,default=DEFAULT_FORECAST_CACHE_SECONDS)\n    p.add_argument("--forecast-raw-gap-min",type=float,default=DEFAULT_FORECAST_RAW_GAP_MIN); p.add_argument("--max-forecast-events",type=int,default=DEFAULT_MAX_FORECAST_EVENTS)\n    p.add_argument("--paper-stake-usd",type=float,default=DEFAULT_PAPER_STAKE_USD); p.add_argument("--once",action="store_true")\n    raise SystemExit(asyncio.run(_main(p.parse_args())))\n\n\nif __name__=="__main__":\n    main()\n')
write('polymarket_scanner/weather_only_maker_paper_accounting_v6.py', 'from __future__ import annotations\n\nimport time\n\nfrom .weather_only_maker_paper_accounting import MAKER_SETTLEMENT_EVENT\nfrom .weather_only_maker_paper_accounting_v5 import MakerPaperAccountingStoreV5\n\nLEGACY_QUEUE_UNCERTIFIED = "LEGACY_QUEUE_UNCERTIFIED"\nRESEARCH_ONLY = "RESEARCH_ONLY"\nCERTIFIED_QUEUE_MODEL = "CERTIFIED_QUEUE_MODEL"\nMAKER_PAPER_ACCOUNTING_V6_VERSION = "weather_maker_v6_explicit_evidence_excludes_legacy_queue_pnl"\n\n\nclass MakerPaperAccountingStoreV6(MakerPaperAccountingStoreV5):\n    """Preserve maker history but keep uncertified queue fills out of validated returns."""\n\n    def __init__(self, path):\n        super().__init__(path)\n        self._evidence_migrate()\n\n    def _evidence_migrate(self) -> None:\n        with self._db_lock:\n            self.db.execute(\n                """CREATE TABLE IF NOT EXISTS weather_maker_evidence_classification(\n                     order_id TEXT PRIMARY KEY,\n                     evidence_class TEXT NOT NULL,\n                     reason TEXT NOT NULL,\n                     classified_at REAL NOT NULL\n                   )"""\n            )\n            # Anything with a historical simulated fill was produced by the old\n            # public-print queue assumption. It remains auditable but can never become\n            # validated performance merely because settlement happens after migration.\n            legacy_ids = {\n                order.order_id for order in self.orders()\n                if float(order.simulated_filled_shares) > 0.0\n            }\n            legacy_ids.update(\n                str(row[0]) for row in self.db.execute(\n                    "SELECT DISTINCT order_id FROM weather_maker_shadow_events WHERE event_type=?",\n                    (MAKER_SETTLEMENT_EVENT,),\n                ).fetchall()\n            )\n            for oid in sorted(legacy_ids):\n                self.db.execute(\n                    """INSERT INTO weather_maker_evidence_classification(\n                         order_id,evidence_class,reason,classified_at\n                       ) VALUES(?,?,?,?)\n                       ON CONFLICT(order_id) DO UPDATE SET\n                         evidence_class=excluded.evidence_class,\n                         reason=excluded.reason""",\n                    (\n                        oid, LEGACY_QUEUE_UNCERTIFIED,\n                        "Historical public-trade queue model was not execution-certified",\n                        time.time(),\n                    ),\n                )\n\n    def evidence_class(self, order_id: str) -> str:\n        with self._db_lock:\n            row = self.db.execute(\n                "SELECT evidence_class FROM weather_maker_evidence_classification WHERE order_id=?",\n                (str(order_id),),\n            ).fetchone()\n        return str(row[0]) if row else RESEARCH_ONLY\n\n    def maker_performance_by_evidence(self) -> dict:\n        buckets = {\n            CERTIFIED_QUEUE_MODEL: {"settled":0,"capital":0.0,"proceeds":0.0,"pnl":0.0},\n            LEGACY_QUEUE_UNCERTIFIED: {"settled":0,"capital":0.0,"proceeds":0.0,"pnl":0.0},\n            RESEARCH_ONLY: {"settled":0,"capital":0.0,"proceeds":0.0,"pnl":0.0},\n        }\n        for order in self.orders():\n            settlement = self.settlement(order.order_id)\n            if not isinstance(settlement, dict):\n                continue\n            cls = self.evidence_class(order.order_id)\n            bucket = buckets.setdefault(cls, {"settled":0,"capital":0.0,"proceeds":0.0,"pnl":0.0})\n            bucket["settled"] += 1\n            bucket["capital"] += float(settlement.get("simulated_capital_used") or 0.0)\n            bucket["proceeds"] += float(settlement.get("paper_proceeds") or 0.0)\n            bucket["pnl"] += float(settlement.get("paper_pnl") or 0.0)\n        for bucket in buckets.values():\n            bucket["roi"] = bucket["pnl"] / bucket["capital"] if bucket["capital"] > 0 else None\n        return {\n            "validated": buckets[CERTIFIED_QUEUE_MODEL],\n            "legacy_excluded": buckets[LEGACY_QUEUE_UNCERTIFIED],\n            "research_excluded": buckets[RESEARCH_ONLY],\n            "validated_evidence_class": CERTIFIED_QUEUE_MODEL,\n        }\n\n    def summary(self) -> dict:\n        out = dict(super().summary())\n        out.update({\n            "version": MAKER_PAPER_ACCOUNTING_V6_VERSION,\n            "maker_evidence_classification": True,\n            "legacy_queue_uncertified_excluded_from_validated_pnl": True,\n            "performance_by_evidence": self.maker_performance_by_evidence(),\n        })\n        return out\n')

